import numpy as np
from scipy.optimize import minimize

try:
    from pyDOE2 import lhs as _lhs
except ImportError:
    try:
        from scipy.stats import qmc
        def _lhs(n_samples, n_dim):
            return qmc.LatinHypercube(d=n_dim).random(n_samples)
    except ImportError:
        raise ImportError("pyDOE2 or scipy required")

class Optimizer:
    def __init__(self, budget: int, dim: int):
        self.budget = budget
        self.dim = dim
        self.evals = 0
        self.best_f = float('inf')
        self.best_x = np.zeros(dim)
        self.rng = np.random.default_rng()
        self.archive = []
        self.archive_cap = 60

    def _evaluate(self, x, func):
        if self.evals >= self.budget: return float('inf')
        x = np.clip(x, -1.0, 1.0)
        f = func(x)
        self.evals += 1
        if f < self.best_f:
            self.best_f = f
            self.best_x = x.copy()
        return f

    def _project_from_cliff(self, x, func, grad_func):
        if grad_func is None:
            return np.clip(x + self.rng.uniform(-0.15, 0.15, 24), -1.0, 1.0), float('inf')
        try:
            g = grad_func(x)
            if g is not None and len(g) == 18:
                g = np.nan_to_num(g, nan=0.0, posinf=0.0, neginf=0.0)
                norm = np.linalg.norm(g)
                if norm > 1e-6:
                    step_dir = -g / norm
                    for step in np.linspace(0.01, 0.25, 15):
                        x_new = np.clip(x + np.concatenate([step_dir * step, np.zeros(6)]), -1.0, 1.0)
                        f_new = self._evaluate(x_new, func)
                        if np.isfinite(f_new): return x_new, f_new
        except Exception: pass
        return np.clip(x + self.rng.uniform(-0.2, 0.2, 24), -1.0, 1.0), float('inf')

    def __call__(self, func, grad_func=None):
        if self.evals >= self.budget: return self.best_f, self.best_x

        n_pop = max(15, min(50, self.budget // 2))
        pop = _lhs(n_samples=n_pop, n_dim=24)
        pop = np.clip(pop * 2.0 - 1.0, -1.0, 1.0)
        fitness = np.array([self._evaluate(p, func) for p in pop])

        max_gen = max(4, min(40, self.budget // n_pop))
        t = 0.0

        for gen in range(max_gen):
            if self.evals >= self.budget: break
            t = gen / max_gen

            f_valid = fitness[np.isfinite(fitness)]
            f_var = np.var(f_valid) if len(f_valid) > 1 else 1e-6
            pop_var = np.var(pop, axis=0)
            diversity_ratio = np.mean(pop_var[:18]) / (np.std(f_valid) + 1e-9)

            # Adaptive mutation parameters
            F = np.clip(0.3 + 0.4 * (1.0 - f_var / (np.abs(f_valid).max() + 1e-9)), 0.1, 0.9)
            gamma = np.clip(1.0 - diversity_ratio * 0.4, 0.0, 1.0)  # Cauchy weight

            best_idx = np.argmin(fitness)
            x_best = pop[best_idx]

            g_bias = np.zeros(18)
            grad_norm = 0.0
            if grad_func:
                try:
                    g = grad_func(x_best)
                    if g is not None and len(g) == 18:
                        g_clean = np.nan_to_num(g, nan=0.0, posinf=0.0, neginf=0.0)
                        grad_norm = np.linalg.norm(g_clean)
                        if grad_norm > 1e-8:
                            g_bias = (g_clean / grad_norm) * (0.04 * (1.0 - t) + 0.02)
                except Exception: pass

            for i in range(n_pop):
                if self.evals >= self.budget: break
                idxs = self.rng.choice(n_pop, 3, replace=False)
                while i in idxs: idxs = self.rng.choice(n_pop, 3, replace=False)

                # Hybrid Gaussian-Cauchy + DE mutation
                mut = x_best + F * (pop[idxs[0]] - pop[idxs[1]])
                scale = 0.015 * (1.0 - t) + 0.01
                gaussian_noise = self.rng.normal(0, 1, 24) * scale
                cauchy_noise = self.rng.standard_cauchy(24) * scale * 0.6
                mut += (1.0 - gamma) * gaussian_noise + gamma * cauchy_noise
                mut[:18] += g_bias
                mut = np.clip(mut, -1.0, 1.0)

                CR = np.clip(0.5 + 0.4 * t, 0.5, 0.95)
                cr_mask = self.rng.random(24) < CR
                trial = np.where(cr_mask, mut, pop[i])
                f_trial = self._evaluate(trial, func)

                # Adaptive cliff recovery
                if np.isinf(f_trial) and self.evals < self.budget:
                    trial_r, f_trial_r = self._project_from_cliff(trial, func, grad_func)
                    if np.isfinite(f_trial_r):
                        trial, f_trial = trial_r, f_trial_r
                    else:
                        trial = np.clip(trial + self.rng.uniform(-0.15, 0.15, 24), -1.0, 1.0)
                        f_trial = self._evaluate(trial, func)

                if f_trial < fitness[i]:
                    pop[i] = trial
                    fitness[i] = f_trial
                    if np.isfinite(f_trial):
                        div_metric = np.linalg.norm(trial - x_best) + 1e-9
                        if len(self.archive) < self.archive_cap:
                            self.archive.append((trial.copy(), f_trial, div_metric))
                        else:
                            worst_idx = np.argmin([a[2] for a in self.archive])
                            if div_metric > self.archive[worst_idx][2]:
                                self.archive[worst_idx] = (trial.copy(), f_trial, div_metric)
                else:
                    if len(f_valid) > 5 and np.var(f_valid) < 1e-7 and self.rng.random() < 0.15:
                        ref_idx = self.rng.choice(len(self.archive)) if self.archive else best_idx
                        pop[i] = self.archive[ref_idx][0].copy()
                        fitness[i] = self._evaluate(pop[i], func)

        # Phase 2: Gradient-Refined Local Search
        if self.evals < self.budget * 0.85 and grad_func:
            top_indices = np.argsort(fitness)[:min(3, n_pop)]
            for idx in top_indices:
                if self.evals >= self.budget or np.isinf(fitness[idx]): continue
                x0 = pop[idx]
                cats = x0[18:]
                conts = x0[:18]

                try:
                    g_init = grad_func(np.concatenate([conts, cats]))
                    if g_init is not None and np.linalg.norm(g_init) < 1e-3: continue
                except Exception: continue

                def cost_wrap(x_c): return self._evaluate(np.concatenate([x_c, cats]), func)
                def grad_wrap(x_c):
                    full = np.concatenate([x_c, cats])
                    try:
                        g = grad_func(full)
                        return np.nan_to_num(g[:18], nan=0.0, posinf=0.0, neginf=0.0) if g is not None else np.zeros(18)
                    except Exception: return np.zeros(18)

                remaining = self.budget - self.evals
                max_iter = min(150, max(30, int(remaining / 3)))
                res = minimize(cost_wrap, conts, jac=grad_wrap, method='L-BFGS-B',
                               bounds=[(-1.0, 1.0)]*18,
                               options={'maxiter': max_iter, 'ftol': 1e-12, 'gtol': 1e-9})
                if np.isfinite(res.fun) and res.fun < self.best_f:
                    self.best_f = res.fun
                    self.best_x = np.concatenate([np.clip(res.x, -1.0, 1.0), cats])

        return self.best_f, self.best_x
